import {progressSummary,refreshLessonCompletion} from './progress.mjs?v=23';
import {normalisationWalkthrough,bindNormalisation} from './normalisation.mjs?v=23';
import {dbUnits as introUnits,dbLessons as introLessons} from './database-data.mjs?v=23';
import {intermediateUnits,intermediateLessons} from './intermediate-data.mjs?v=23';
const dbUnits=[...introUnits,...intermediateUnits],dbLessons=[...introLessons,...intermediateLessons];
import {workStore} from './work-store.mjs?v=15';
import {escapeHTML as e} from './engine.mjs?v=17';
export {dbUnits,dbLessons};
const code=text=>`<pre><code>${e(text)}</code></pre>`;
const link=l=>`<a href="#db-lesson/${l.id}">${e(l.title)}</a>`;
export function databaseHome({view,sidebar}){const intermediate=location.hash.startsWith('#db-intermediate'),courseUnits=intermediate?intermediateUnits:introUnits;view.innerHTML=`<section class="welcome"><p class="eyebrow">${intermediate?'DATABASE INTERMEDIATE . DATA6222':'DATABASE INTRODUCTION . DATA6211 / DATA6211w'}</p><h1>Understand data. Build better databases.</h1><p class="lede">Start with the ideas, design the relationships, then put SQL into practice. Choose a learning unit below.</p><div class="button-row"><a class="button" href="#db-unit/${intermediate?101:1}">Start with Unit 1</a><a class="button secondary" href="#sql">Open SQL workspace</a></div></section>${progressSummary(intermediate?'intermediate':'database')}<div class="section-heading"><h2>Explore the database course</h2><p>${intermediate?'Nine units, 106 outcomes, 27 lessons and native SQL Server examples.':'Six units with expanded tasks, worked examples and SQL practice.'}</p></div>${courseUnits.map(u=>`<article class="course-unit"><div class="course-unit-title"><span class="unit-badge">${String(u.number||u.id).padStart(2,'0')}</span><div><h2><a href="#db-unit/${u.id}">${e(u.title)}</a></h2><p>${e(u.subtitle)}</p><a class="text-link" href="#db-unit/${u.id}">Read unit overview</a></div></div><div class="course-lesson-links">${dbLessons.filter(l=>l.unit===u.id).map(link).join('')}</div></article>`).join('')}<div class="button-row"><a class="button secondary" href="#db">Introduction . DATA6211</a><a class="button secondary" href="#db-intermediate">Intermediate . DATA6222</a></div><p class="note">Original supplementary material aligned to the supplied course outlines. Textbook chapter numbers follow that outline; these lessons do not reproduce the prescribed textbook.</p>`;sidebar();}
export function databaseUnit({view,id,sidebar}){const u=dbUnits.find(u=>u.id===Number(id));if(!u){location.hash='db';return;}const ls=dbLessons.filter(l=>l.unit===u.id),number=u.number||u.id,home=u.id>100?'db-intermediate':'db';view.innerHTML=`<p class="breadcrumb"><a href="#${home}">Databases</a><span>/</span><strong>Unit ${number} overview</strong></p><p class="eyebrow">${u.id>100?'DATA6222':'DATA6211 / DATA6211w'} . LEARNING UNIT ${number}</p><h1>${e(u.title)}</h1><p class="lede">${e(u.overview)}</p><section class="panel unit-overview-panel"><h2>What you will learn</h2><ol>${u.outcomes.map(o=>`<li>${e(o)}</li>`).join('')}</ol><h3>Themes in this unit</h3><ul>${u.themes.map(t=>`<li>${e(t)}</li>`).join('')}</ul><p><strong>Outline reference:</strong> prescribed textbook chapter ${e(u.chapter)}. ${e(u.sessions)}</p><h3>How to study this unit</h3><p>Read each lesson and work through its example. Attempt the quiz and written task before revealing the explanation. ${u.id===6?'Run the SQL examples using the demo data and inspect the result tables.':'Explain your design decisions in your own words and check them against the business rules.'}</p><div class="note"><strong>Before moving on:</strong> ${e(u.check)}</div><div class="button-row"><a class="button" href="#db-lesson/${ls[0].id}">Start this unit</a>${u.id===6?'<a class="button secondary" href="#sql">Practise SQL</a>':''}<button class="button secondary" id="print-db-unit">Print / save overview as PDF</button></div></section><div class="section-heading"><h2>Lessons in this unit</h2></div><div class="lesson-list">${ls.map((l,i)=>`<article class="lesson-row"><span class="sequence">${i+1}</span><div><h3>${e(l.title)}</h3><p>Explanation, worked example, quiz and practice.</p></div><a class="button secondary" href="#db-lesson/${l.id}">Open lesson</a></article>`).join('')}</div>`;view.querySelector('#print-db-unit').onclick=()=>window.print();sidebar(u.id);}
export function collegeDiagram(){return `<figure class="db-diagram"><svg viewBox="0 0 820 270" role="img" aria-label="Students and Courses each have zero or many Enrolments; every Enrolment has exactly one Student and one Course." xmlns="http://www.w3.org/2000/svg"><defs><marker id="db-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#245b8e"/></marker></defs>${[[15,50,'Students',['PK StudentID','StudentName','City','Age']],[305,50,'Enrolments',['PK EnrolmentID','FK StudentID','FK CourseID','Mark (may be NULL)']],[595,50,'Courses',['PK CourseID','CourseName','Fee']]].map(([x,y,title,attrs])=>`<g><rect x="${x}" y="${y}" width="210" height="175" rx="8" fill="#edf4ff" stroke="#6a90b9"/><rect x="${x}" y="${y}" width="210" height="38" rx="8" fill="#245b8e"/><text x="${x+14}" y="${y+25}" fill="white" font-size="18" font-weight="bold">${title}</text>${attrs.map((a,i)=>`<text x="${x+14}" y="${y+65+i*25}" fill="#19344c" font-size="15">${e(a)}</text>`).join('')}</g>`).join('')}<path d="M225 130 H305 M595 130 H515" stroke="#245b8e" stroke-width="2" fill="none"/><text x="233" y="118" fill="#19344c" font-size="14">1</text><text x="265" y="118" fill="#19344c" font-size="14">0..*</text><text x="526" y="118" fill="#19344c" font-size="14">0..*</text><text x="577" y="118" fill="#19344c" font-size="14">1</text><text x="305" y="252" fill="#19344c" font-size="14">UNIQUE (StudentID, CourseID)</text></svg><figcaption>Labelled relational ERD. PK = primary key. FK = foreign key. 0..* = zero or many. Each enrolment must reference one existing student and one existing course.</figcaption></figure>`;}
function cleanLesson(raw){return {revision:typeof raw?.revision==='string'?raw.revision.slice(0,40):'',tab:['learn','quiz','practice'].includes(raw?.tab)?raw.tab:'learn',choices:Array.isArray(raw?.choices)?raw.choices.slice(0,2).map(v=>Number.isInteger(v)&&v>=0&&v<5?v:null):[],taskIndex:Number.isInteger(raw?.taskIndex)&&raw.taskIndex>=0&&raw.taskIndex<10?raw.taskIndex:0,checked:Array.isArray(raw?.checked)?raw.checked.slice(0,2).map(Boolean):[],draft:typeof raw?.draft==='string'?raw.draft.slice(0,20000):'',attempted:!!raw?.attempted,hint:!!raw?.hint,revealed:!!raw?.revealed};}
export function databaseLesson({view,id,task,sidebar}){const l=dbLessons.find(l=>l.id===id);if(!l){location.hash='db';return;}let state=workStore.read('database:'+id,cleanLesson({}),cleanLesson);if(/^task-[0-9]+$/.test(task||'')){state.taskIndex=Math.min(Number(task.slice(5)),(l.tasks||[l.task]).length-1);state.tab='practice';}const save=()=>{workStore.write('database:'+id,state);refreshLessonCompletion(view,id,l.unit>100?'intermediate':'database');};const courseLessons=dbLessons.filter(x=>(x.unit>100)===(l.unit>100)),idx=courseLessons.indexOf(l),number=l.unit>100?l.unit-100:l.unit,home=l.unit>100?'db-intermediate':'db';
 view.innerHTML=`<p class="breadcrumb"><a href="#${home}">Databases</a><span>/</span><a href="#db-unit/${l.unit}">Unit ${number} overview</a></p><p class="eyebrow">${l.unit>100?'DATA6222':'DATA6211'} . UNIT ${number}</p><h1>${e(l.title)}</h1><div class="lesson-tabs" role="tablist" aria-label="Database lesson sections">${[['learn','Learn'],['quiz','Quiz'],['practice','Try it yourself']].map(([key,label])=>`<button id="db-tab-${key}" role="tab" data-db-tab="${key}" aria-controls="db-panel">${label}</button>`).join('')}</div><section id="db-panel" class="panel" role="tabpanel"></section><nav class="lesson-paging" aria-label="Lesson navigation">${idx?`<a class="button secondary" href="#db-lesson/${courseLessons[idx-1].id}">Previous lesson</a>`:`<a class="button secondary" href="#db-unit/${l.unit}">Unit overview</a>`}${idx<courseLessons.length-1?`<a class="button" href="#db-lesson/${courseLessons[idx+1].id}">Next lesson</a>`:'<a class="button" href="#sql">Practise SQL</a>'}</nav><button class="button secondary" id="db-print">Print / save this view as PDF</button>`;
 const render=()=>{view.querySelectorAll('[data-db-tab]').forEach(b=>{const selected=b.dataset.dbTab===state.tab;b.classList.toggle('active',selected);b.setAttribute('aria-selected',selected);b.tabIndex=selected?0:-1;});const panel=view.querySelector('#db-panel');panel.setAttribute('aria-labelledby','db-tab-'+state.tab);
 if(state.tab==='learn'){panel.innerHTML=`<div class="theory">${l.sections.map(s=>`<h2>${e(s.heading)}</h2><p>${e(s.text)}</p>`).join('')}<h2>Worked example: ${e(l.example.title)}</h2><p>${e(l.example.problem)}</p><div class="worked-explanation"><h3>Solution and reasoning</h3><p>${e(l.example.solution)}</p></div>${l.sampleCode?`<h3>${l.environment==='native'?'SQL Server / SSMS example':l.environment==='design'?'Design and dependency example':'Portable SQL example'}</h3>${code(l.sampleCode)}<div class="button-row"><button class="button secondary" id="db-copy-code">Copy example</button><a class="button secondary" href="./downloads/intermediate/${e(l.download)}" download>Download example</a></div><p id="db-copy-status" role="status"></p>`:''}${(l.moreExamples||[]).map(x=>`<h3>Additional example: ${e(x.title)}</h3><p class="note">${x.environment==='native'?'Run in SQL Server / SSMS.':'Portable SQL: use the college workspace.'}</p>${code(x.code)}<p>${e(x.reason)}</p>`).join('')}${l.diagram==='college'?collegeDiagram():l.diagram?normalisationWalkthrough():''}${l.sql?`<a class="button" href="#sql/${l.sql}">Run a related SQL example</a>`:''}</div>`;if(l.sampleCode){panel.querySelector('#db-copy-code').onclick=async()=>{try{await navigator.clipboard.writeText(l.sampleCode);panel.querySelector('#db-copy-status').textContent='Example copied.';}catch{panel.querySelector('#db-copy-status').textContent='Select the code above and copy it using your keyboard.';}};}if(l.diagram&&l.diagram!=='college')bindNormalisation(panel);}
 else if(state.tab==='quiz'){panel.innerHTML=`<p class="muted">Choose an answer and check it. You can retry.</p>${l.quizzes.map((q,i)=>`<form class="db-quiz" data-quiz="${i}"><fieldset><legend>${i+1}. ${e(q.question)}</legend>${q.options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="answer" value="${j}" required ${state.choices[i]===j?'checked':''}>${e(o)}</label>`).join('')}</fieldset><button class="button" type="submit">Check answer ${i+1}</button><p class="feedback" role="status">${state.checked[i]?`${state.choices[i]===q.answer?'Correct.':'Not quite.'} ${e(q.explanation)}`:''}</p></form>`).join('')}`;panel.querySelectorAll('form').forEach(form=>{const i=Number(form.dataset.quiz);form.onchange=()=>{state.choices[i]=Number(new FormData(form).get('answer'));state.checked[i]=false;form.querySelector('.feedback').textContent='Answer selected. Check it when ready.';save();};form.onsubmit=event=>{event.preventDefault();if(!form.reportValidity())return;state.choices[i]=Number(new FormData(form).get('answer'));state.checked[i]=true;save();render();};});}
 else{const tasks=l.tasks||[l.task];state.taskIndex=Math.min(state.taskIndex||0,tasks.length-1);const task=tasks[state.taskIndex],key='database:'+id+':task-'+state.taskIndex;let ps=state.taskIndex===0?state:workStore.read(key,cleanLesson({}),cleanLesson);const updatedTask=!!task.revision&&task.revision!==ps.revision&&!!ps.draft;const savePractice=()=>{ps.revision=task.revision||'';return state.taskIndex===0?save():workStore.write(key,ps);};panel.innerHTML=`<h2>Try it yourself</h2><label class="field-label" for="db-task-select">Practice task</label><select id="db-task-select" aria-label="Practice task">${tasks.map((t,i)=>`<option value="${i}" ${i===state.taskIndex?'selected':''}>${i+1}. ${e(t.title||'Task '+(i+1))}</option>`).join('')}</select><p>${e(task.prompt)}</p>${updatedTask?'<p class="note">This task has been updated. Your earlier draft is retained below; review it against the new instructions.</p>':''}${task.sqlChallenge?`<a class="button secondary" href="#sql/challenge-${e(task.sqlChallenge)}">Solve in SQL workspace with automatic marking</a>`:''}<form id="db-task"><label class="field-label">Your explanation or SQL<textarea id="db-answer" rows="8" maxlength="20000" required>${e(ps.draft)}</textarea></label><div class="button-row"><button class="button" type="submit">Submit my attempt</button><button class="button secondary" type="button" id="db-hint">Give me a hint</button><button class="button secondary" type="button" id="db-solution" ${ps.attempted?'':'disabled'}>Reveal worked answer</button></div><p id="db-task-status" class="muted" role="status">${ps.attempted?'Attempt saved. Compare it with the worked answer. This written task is self-assessed.':'Write an attempt before revealing the answer. Written answers are self-assessed.'}</p></form><p class="note" id="db-hint-text" ${ps.hint?'':'hidden'}>${e(task.hint)}</p><div class="model-answer" id="db-worked" ${ps.attempted&&ps.revealed?'':'hidden'}><h3>Worked answer</h3>${code(task.solution)}</div>`;
 panel.querySelector('#db-task-select').onchange=event=>{state.taskIndex=Number(event.target.value);save();render();};const input=panel.querySelector('#db-answer');input.oninput=()=>{ps.draft=input.value;savePractice();};panel.querySelector('#db-task').onsubmit=event=>{event.preventDefault();if(!input.value.trim()){panel.querySelector('#db-task-status').textContent='Write your attempt first.';return;}ps.draft=input.value;ps.attempted=true;savePractice();render();};panel.querySelector('#db-hint').onclick=()=>{ps.hint=true;savePractice();panel.querySelector('#db-hint-text').hidden=false;};panel.querySelector('#db-solution').onclick=()=>{if(!ps.attempted)return;ps.revealed=true;savePractice();panel.querySelector('#db-worked').hidden=false;};}
 };
 view.querySelectorAll('[data-db-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.dbTab;save();render();});view.querySelector('.lesson-tabs').onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...view.querySelectorAll('[data-db-tab]')],i=tabs.findIndex(b=>b.dataset.dbTab===state.tab),n=event.key==='Home'?0:event.key==='End'?2:(i+(event.key==='ArrowRight'?1:-1)+3)%3;tabs[n].click();tabs[n].focus();};view.querySelector('#db-print').onclick=()=>window.print();render();sidebar(l.unit);refreshLessonCompletion(view,id,l.unit>100?'intermediate':'database',true);}
export function databasePractice({view,sidebar}){view.innerHTML=`<p class="eyebrow">DATABASES . PRACTICE</p><h1>Choose what to practise.</h1><p class="lede">Use lesson quizzes for quick checks, written tasks for design reasoning, and the SQL workspace for executable queries.</p><div class="hub-grid"><article class="panel hub-card"><h2>Database practice exams</h2><p>Mixed-unit quiz questions, two written tasks, optional timers and worked solutions after submission.</p><div class="button-row"><a class="button" href="#db-exams/database">DATA6211 exam</a><a class="button secondary" href="#db-exams/intermediate">DATA6222 exam</a></div></article><article class="panel hub-card"><h2>Write and run SQL</h2><p>Two fictional datasets, three dialect choices, query examples and practical challenges.</p><a class="button" href="#sql">Open SQL workspace</a></article><article class="panel hub-card"><h2>Normalisation walkthrough</h2><p>Compare 1NF, 2NF and 3NF with dependencies, keys and a complete worked example.</p><a class="button" href="#db-lesson/first-second-nf">Work through normalisation</a></article></div><h2>Quizzes and written tasks by unit</h2><div class="course-lesson-links">${dbUnits.map(u=>`<a href="#db-unit/${u.id}">${u.id>100?'Intermediate':'Introduction'} Unit ${u.number||u.id}: ${e(u.title)}</a>`).join('')}</div><p class="note">Each database lesson has a Quiz and a Try it yourself tab. Written model answers unlock after you submit an attempt.</p>`;sidebar();}
export function databaseResources({view,sidebar}){view.innerHTML=`<p class="eyebrow">DATABASES . RESOURCES</p><h1>Take your practice further.</h1><p class="lede">Download native demo setup scripts from the SQL workspace, or print a unit overview or lesson as PDF.</p><section class="panel"><h2>Database study packs</h2><p>Revision selections with matching question numbers. The full exercise bank remains online.</p>${[['data6211','DATA6211 Introduction',18,14],['data6222','DATA6222 Intermediate',27,20]].map(([code,title,count,slides])=>`<h3>${title}</h3><p>${count} written revision questions and model answers, plus a ${slides}-slide editable revision deck.</p><div class="button-row"><a class="button secondary" href="./downloads/databases/${code}-questions.pdf" download>Questions PDF</a><a class="button secondary" href="./downloads/databases/${code}-questions.docx" download>Questions Word</a><a class="button secondary" href="./downloads/databases/${code}-answers.pdf" download>Answers PDF</a><a class="button secondary" href="./downloads/databases/${code}-answers.docx" download>Answers Word</a><a class="button secondary" href="./downloads/databases/${code}-revision.pptx" download>Revision PowerPoint</a></div>`).join('')}</section><section class="panel"><h2>Native SQL Server verification</h2><p>Native execution is pending. This build environment has no SQL Server instance. The validation harness checks constraints, referential actions, transactions, OUTPUT, indexes, views, procedures and runtime error handling when you run it in a disposable SQL Server database.</p><a class="button secondary" href="./downloads/databases/sqlserver-validation.sql" download>Download native validation script</a><p>Create and select a disposable user database named StudyLabNativeValidation in SSMS. Review the script, run it, and keep its PASS output. It rejects other database contexts and rolls back its fixture objects. This harness covers representative behaviours; it does not certify every lesson example.</p></section><div class="hub-grid"><article class="panel hub-card"><h2>Demo data and SQL scripts</h2><p>Select Microsoft SQL Server, PostgreSQL or MySQL, then download the setup script and your current query.</p><a class="button" href="#sql">Open SQL downloads</a></article><article class="panel hub-card"><h2>Unit overview sheets</h2><p>Each overview includes outcomes, themes, study guidance and a printable summary.</p><a class="button" href="#db">Choose a learning unit</a></article></div><section class="panel"><h2>DATA6222 Intermediate examples</h2><p>In SSMS, select a disposable user database and run the college setup first. Each lesson labels its environment and prerequisites. Design notation downloads as text. Native scripts have been reviewed but have not been executed on a SQL Server instance here.</p><a class="button secondary" href="./downloads/intermediate/college-setup.sql" download>Download college setup for SQL Server</a>${intermediateUnits.map(u=>`<h3>Unit ${u.number}: ${e(u.title)}</h3><ul>${intermediateLessons.filter(l=>l.unit===u.id).map(l=>`<li><a href="./downloads/intermediate/${e(l.download)}" download>${e(l.title)} (${l.environment==='design'?'design text':'SQL'})</a> · <a href="#db-lesson/${l.id}">Read lesson</a></li>`).join('')}</ul>`).join('')}</section><section class="panel"><h2>Official reference documentation</h2><ul><li><a class="text-link" href="https://learn.microsoft.com/sql/t-sql/queries/select-transact-sql/" target="_blank" rel="noopener">Microsoft SQL Server SELECT reference</a></li><li><a class="text-link" href="https://www.postgresql.org/docs/current/sql-select.html" target="_blank" rel="noopener">PostgreSQL SELECT reference</a></li><li><a class="text-link" href="https://dev.mysql.com/doc/refman/8.4/en/select.html" target="_blank" rel="noopener">MySQL SELECT reference</a></li><li><a class="text-link" href="https://sql.js.org/" target="_blank" rel="noopener">sql.js: the local SQLite engine used in this workspace</a></li></ul><p class="muted">Database question sheets, model answers and revision PowerPoints are available above. PRLD downloads remain in the PRLD module.</p></section>`;sidebar();}
